207	function checkCorpWinConditions(state) {
208	  if (state.corporate.rank === "P10") {
209	    state.flags.victory = true;
210	    state.flags.victoryType = "p10";
211	    state.flags.gameOver = true;
212	    showVictoryModal();
213	    return true;
214	  }
215	  if (state.resources.cash + state.resources.bankBalance >= 20000000) {
216	    state.flags.victory = true;
217	    state.flags.victoryType = "money";
218	    state.flags.gameOver = true;
219	    showVictoryModal();
220	    return true;
221	  }
222	  return false;
223	}
