225	function checkCorpLoseConditions(state) {
226	  const c = state.player.corporate;
227	  const corp = state.corporate;
228	
229	  // 尊严归零 -> 精神崩溃（不可逆，Game Over）
230	  if (c.dignity <= 0) {
231	    state.flags.gameOver = true;
232	    state.flags.gameOverReason =
233	      "尊严耗尽——长期的精神压力让你选择了离开这个世界...";
234	    showGameOverModal();
235	    return true;
236	  }
237	
238	  // 35岁危机 -> P8以下不可逆淘汰
239	  if (state.player.age >= 35) {
240	    const rankIdx = ["P5", "P6", "P7", "P8", "P9", "P10"].indexOf(
241	      state.corporate.rank,
242	    );
243	    if (rankIdx < 3) {
244	      state.flags.gameOver = true;
245	      state.flags.gameOverReason = `35岁危机——${state.player.age}岁了还只是${state.corporate.rank}，被公司优化了...`;
246	      showGameOverModal();
247	      return true;
248	    }
249	  }
250	
251	  // 以下情况触发「被开除回街头」降级而非 Game Over
252	  let downgradeReason = null;
253	
254	  if (c.hair <= 0) {
255	    downgradeReason =
256	      "过劳到发量归零，被公司劝退休养。你回到了城中村重新开始。";
257	  }
258	  if (c.risk >= 100) {
259	    downgradeReason = "风险值爆表——触碰合规红线，被公司开除。你回到了街头。";
260	  }
261	  if (corp.consecutiveC >= 8) {
262	    downgradeReason = "连续2年绩效为C，被末位淘汰。你带着简历回到了城中村。";
263	  }
264	
265	  if (downgradeReason) {
266	    downgradeToStreet(state, downgradeReason);
267	    return true;
268	  }
269	
270	  return false;
271	}
