283	
284	  // 保留职场期间累积的投资
285	  // 重置职场状态
286	  state.player.phase = "street";
287	  state.corporate.rank = "P5";
288	  state.corporate.actionsUsed = 0;
289	  state.corporate.consecutiveC = 0;
290	  state.corporate.perfHistory = [];
291	  state.corporate.completedProjects = [];
292	  state.corporate.team = [];
293	  state.player.corpYear = 0;
294	  state.player.corpQuarter = 1;
