299	  state.player.corporate.hair = 100;
300	  state.player.corporate.dignity = Math.min(
301	    100,
302	    Math.round(state.player.mental * 1.2),
303	  );
304	  state.player.corporate.upwardMgmt = 20;
305	  state.player.corporate.kpi = 20;
306	  state.player.corporate.ability = Math.min(
307	    100,
308	    Math.round(state.player.intelligence * 0.8 + 10),
309	  );
310	  state.player.corporate.risk = 0;
311	  state.player.corporate.popularity = 25;
312	
313	  // 回到城中村
