782	/** P2.11 计算新游戏+继承内容 */
783	function buildNgPlusData(state) {
784	  var data = { version: 1, victoryType: state.flags.victoryType || "normal" };
785	  // 起始现金奖励（基于上局总收入的1%，上限5000）
786	  var totalEarned = state.resources.totalEarned || 0;
787	  data.startCash = Math.min(5000, Math.floor(totalEarned * 0.01));
788	  // 继承最高技能（在新游戏中从20级开始）
789	  var topSkill = null,
790	    topLvl = 0;
791	  var skills = state.skills || {};
792	  for (var sk in skills) {
793	    if (skills[sk] && (skills[sk].level || 0) > topLvl) {
794	      topLvl = skills[sk].level;
795	      topSkill = sk;
796	    }
797	  }
798	  data.inheritSkill = topSkill;
799	  data.inheritSkillLevel = Math.min(20, Math.floor(topLvl * 0.2));
800	  // 继承声誉（如果有历史声誉标签）
801	  if (typeof getHistoryModifiers === "function") {
802	    var rep = getHistoryModifiers(state).reputationLabel;
803	    if (rep) data.reputationLabel = rep;
804	  }
805	  // 属性小头部奖励（上局最高属性的10%加成，最多+5）
806	  var p = state.player;
807	  var maxStat = Math.max(
808	    p.intelligence || 0,
809	    p.physique || 0,
810	    p.agility || 0,
811	    p.mental || 0,
812	  );
813	  data.statBonus = Math.min(5, Math.floor(maxStat * 0.1));
814	  return data;
815	}
