 */

/** 街头阶段通用行动（不依赖地点） */
function addStreetExtras(state, actions) {
  // === 街头生存类（任何街头地点都行） ===
  actions.push({
    id: "scavenge_trash",
    name: "规划拾荒路线",
    desc: "选择今天的拾荒区域：城中村小巷(稳)/废品站边缘(中)/工业区(高)/老周专线(⭐)。不同路线收益和风险各异。",
    icon: "🗺️",
    apCost: 15,
    payEstimate: "2~65",
    handler: () => {
      showScavengeRouteModal();
    },
  });

  actions.push({
    id: "vending_advice",
    name: "摆摊选址建议",
    desc: "根据天气、节日、周末等因素，智能推荐今日最佳摆摊地点。",
    icon: "📍",
    apCost: 5,
